import { randomUUID } from 'node:crypto';
const sessions = new Map();
const orders = [];
const items = [{ id: 1, title: 'Distributed Systems' }];

export default async function(req, ctx) {
  await ctx.sleep(10);
  if (req.path === '/login' && req.method === 'POST') {
    const { username } = JSON.parse(req.body);
    const token = randomUUID();
    sessions.set(token, username);
    return { token, username };
  }
  const user = sessions.get((req.headers.authorization || '').replace('Bearer ', ''));
  if (!user) return ctx.reply(401, { error: 'Please log in' });
  if (req.path.startsWith('/checkout') && req.method === 'POST') {
    orders.push({ user, ...JSON.parse(req.body), id: orders.length + 1 });
    return { order: orders.at(-1), totalOrders: orders.length };
  }
  return { user, items, totalOrders: orders.length };
}

