import http from 'k6/http';
import { check, sleep } from 'k6';
import exec from 'k6/execution';

export const options = {
  noCookiesReset: true,
  stages: [
    { duration: __ENV.RAMP + 's', target: Number(__ENV.USERS) },
    { duration: __ENV.DURATION + 's', target: Number(__ENV.USERS) },
    { duration: '3s', target: 0 },
  ],
  thresholds: { http_req_failed: ['rate<0.05'], http_req_duration: ['p(95)<1000'] },
};

// Module state is isolated per virtual user and survives their iterations.
let token;
const think = () => sleep(0.5 + Math.random() * 1.5);

export default function() {
  const base = __ENV.TARGET;
  if (!token) {
    const login = http.post(base + '/login', JSON.stringify({
      username: 'shopper-' + exec.vu.idInTest,
    }), { headers: { 'Content-Type': 'application/json' }, tags: { name: 'Log in' } });
    if (!check(login, { 'login succeeds': r => r.status === 200 })) {
      think();
      return;
    }
    token = login.json('token');
    think();
  }
  const params = { headers: { Authorization: 'Bearer ' + token, 'Content-Type': 'application/json' } };
  const catalog = http.get(base + '/catalog', { ...params, tags: { name: 'Browse catalog' } });
  check(catalog, { 'catalog loads': r => r.status === 200 });
  think();
  // Most visits browse; some users choose to buy.
  if (Math.random() < 0.25) {
    const order = http.post(base + '/checkout', JSON.stringify({ item: 1 }),
      { ...params, tags: { name: 'Place order' } });
    check(order, { 'order accepted': r => r.status === 200 });
    think();
  }
}

