export const options = {
  noCookiesReset: true,
  stages: [
    { duration: __ENV.RAMP + 's', target: Number(__ENV.USERS) },
    { duration: __ENV.DURATION + 's', target: Number(__ENV.USERS) },
    { duration: '3s', target: 0 },
  ],
  thresholds: { http_req_failed: ['rate<0.05'], http_req_duration: ['p(95)<1500'] },
};

const think = () => sleep(1 + Math.random() * 3);
export default function() {
  const base = __ENV.TARGET;
  group('Browse FreshPhones', function() {
    const home = http.get(base + '/', { tags: { name: 'Home page' } });
    check(home, { 'home loads': r => r.status === 200 });
    think();
    const catalog = http.get(base + '/api/catalog', { tags: { name: 'Public catalog' } });
    check(catalog, { 'catalog available': r => r.status === 200 });
    think();
    if (Math.random() < 0.3) {
      const about = http.get(base + '/about', { tags: { name: 'About and verification' } });
      check(about, { 'about loads': r => r.status === 200 });
      think();
      const lookup = http.get(base + '/api/agents/verify?q=Lab%20Test', { tags: { name: 'Agent lookup' } });
      check(lookup, { 'lookup available': r => r.status === 200 });
      think();
    }
  });
  // Public, read-only traffic is ready out of the box.
  // For staff/customer flows, seed synthetic accounts in freshphones_lab,
  // then POST /api/auth/login with email/password and an Origin header
  // matching http://localhost:18080. k6 keeps each VU's cookie jar separate.
  // Real rate limits stay enabled: HTTP 429 counts as a failed request.
}
